import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,viewFor,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const lightKingCard='a2-p16-r3c3';
export const lightKingScenarios=['light-king-ordinary','light-king-owner-ordinary','light-king-owner-dedicated','light-king-precheck-fail','light-king-usage-fail','light-king-evil','light-king-low-effect','light-king-root','light-king-decline','light-king-group','light-king-group-multi','light-king-group-self','light-king-group-fail','light-king-group-fate','light-king-group-no-maai-ignore','light-king-group-counter-prohibited','light-king-return-water','light-king-return-maai','light-king-return-evade','light-king-reroll'] as const;
export const lightKingBrowserScenarios=['light-king-ui-group', 'light-king-ui-group-multi', 'light-king-ui-group-self', 'light-king-ui-group-fail', 'light-king-ui-group-fate', 'light-king-ui-group-no-maai-ignore', 'light-king-ui-group-counter-prohibited', 'light-king-ui-return-water', 'light-king-ui-return-maai', 'light-king-ui-return-evade', 'light-king-ui-reroll'] as const;
export type LightKingScenario=typeof lightKingScenarios[number]|typeof lightKingBrowserScenarios[number];
export function isLightKingScenario(name:string):name is LightKingScenario{return (lightKingScenarios as readonly string[]).includes(name)||(lightKingBrowserScenarios as readonly string[]).includes(name);}
export function lightKingMode(name:LightKingScenario){const suffix=name.replace('light-king-ui-','').replace('light-king-',''),group=suffix.startsWith('group')||suffix.startsWith('return')||suffix==='reroll',owner=group||suffix.startsWith('owner'),dedicated=group||suffix==='owner-dedicated',multi=suffix==='group-multi',nightmare=suffix==='group-no-maai-ignore',prohibited=suffix==='group-counter-prohibited',targets=group?(suffix==='group-self'?[1,2,3]:[1,3]):[2];return {suffix,group,owner,dedicated,multi,nightmare,prohibited,targets};}
export function makeLightKingPhysical(name:LightKingScenario,players:{id:string;name:string}[],options:{spirit?:number}={}){const m=lightKingMode(name);let s=createGame(players,entropy(),{startingSeat:m.suffix==='root'?2:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.multi?'侍大将のシン':m.nightmare?'魔聖母ディア':m.prohibited?'吟遊詩人のレスター':'黒騎士ガーウィン','黒妖精のアーネス',m.owner?'リーア姫':m.suffix==='evil'?'魔導王ガイナス':'白魔術師シェリム','小人のランバ'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===c?(options.spirit??(name.startsWith('light-king-ui-')?(m.suffix==='group-fail'?3:15):m.suffix==='low-effect'?1:6)):12)-gameStats(s,p.id).spirit;}
 if(m.suffix==='usage-fail')s.players[c]!.permanent!.magic_level!+=5-gameStats(s,c).magic_level;
 const source=takeCard(s,a,m.group?(m.multi?'天地百撃斬':m.nightmare?'悪夢':m.prohibited?'死歌':'魔空剣'):'踏み込み／弓'),keep=[source,takeCard(s,c,lightKingCard),takeCard(s,d,'命運凶変'),takeCard(s,d,'神性介入')];if(m.suffix==='return-water'||m.nightmare)keep.push(takeCard(s,a,'水竜'));if(m.suffix==='return-maai')keep.push(takeCard(s,a,'a2-p06-r1c3'));if(m.suffix==='return-evade')keep.push(takeCard(s,a,'a2-p05-r3c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`LIGHT_KING_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('LIGHT_KING_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('LIGHT_KING_CARDS');}
 for(const id of [a,b,c,d]){if(id===a&&(m.suffix==='return-water'||m.nightmare))act(a,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:'a2-p23-r1c1'});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));const starter=m.suffix==='root'?c:a;act(starter,{type:'START_TURN'});act(starter,{type:'CHOOSE_DRAW',draw:false});if(m.suffix==='root')return s;
 if(m.multi||m.prohibited){act(a,{type:'CHANT',cardInstanceId:source,dedicated:true});for(let n=0;n<250;n++){const id=s.seatOrder[s.turnSeat]!,w=s.windows?.at(-1);if(w)act(w.participants[w.cursor]!,{type:'PASS'});else if(s.phase==='action'){if(id===a)break;act(id,{type:'PASS_ACTION'});}else if(s.phase==='withdrawal')act(id,{type:'PASS_WITHDRAWAL'});else if(s.phase==='hand-adjustment')act(id,{type:'END_TURN',discardIds:s.players[id]!.hand.slice(gameStats(s,id).handLimit)});else if(s.phase==='turn-start')act(id,{type:'START_TURN'});else if(s.phase==='draw')act(id,{type:'CHOOSE_DRAW',draw:false});}}
 act(a,{type:'ATTACK',cardInstanceId:source,targetIds:m.targets.map(i=>players[i]!.id),dedicated:m.group});for(let n=0;n<500;n++){const w=s.windows?.at(-1)!;if(m.group?w.kind==='attack-abilities'&&w.participants[w.cursor]===c:w.kind==='normal-defense'&&w.participants[w.cursor]===c)return s;act(w.participants[w.cursor]!,{type:'PASS'},m.multi&&w.kind==='damage'?3:1);}throw Error('LIGHT_KING_WINDOW');
}
